                        seen.add((nr, nc))
                        queue.append((nr, nc))
            result.append((color, cells))
    return result


def _shape(cells):
    min_r = min(r for r, c in cells)
    min_c = min(c for r, c in cells)
    return {(r - min_r, c - min_c) for r, c in cells}


def _strict_corner_l(cells):
    shape = _shape(cells)
    h = max(r for r, c in shape) + 1
    w = max(c for r, c in shape) + 1
    if h < 2 or w < 2:
        return False
    for r in (0, h - 1):
        for c in (0, w - 1):
            if shape == ({(r, j) for j in range(w)} | {(i, c) for i in range(h)}):
                return True
    return False


def _touches_adjacent_edges(cells, h, w):
    rows = [r for r, c in cells]
    cols = [c for r, c in cells]
    return (min(rows) == 0 or max(rows) == h - 1) and (min(cols) == 0 or max(cols) == w - 1)


def _canonical_shape(cells):
    points = list(_shape(cells))
    variants = []
    for flip in (False, True):
        for rotations in range(4):
            transformed = []
            for r, c in points:
                if flip:
                    c = -c
                for _ in range(rotations):
                    r, c = c, -r
                transformed.append((r, c))
            min_r = min(r for r, c in transformed)
            min_c = min(c for r, c in transformed)
            variants.append(tuple(sorted((r - min_r, c - min_c) for r, c in transformed)))
    return min(variants)


def _centroid(cells):
    return (sum(r for r, c in cells) / len(cells), sum(c for r, c in cells) / len(cells))


def _nonlinear_or_single(cells):
    if len(cells) == 1:
        return True
    shape = _shape(cells)
    h = max(r for r, c in shape) + 1
    w = max(c for r, c in shape) + 1
    return h > 1 and w > 1


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    objects = [(color, cells) for color, cells in _components(grid) if color != background]

    guides = [(color, cells) for color, cells in objects
              if _strict_corner_l(cells) and _touches_adjacent_edges(cells, h, w)]
    if not guides:
        return [row[:] for row in grid]
    guide_color, guide_cells = max(guides, key=lambda item: len(item[1]))
    guide_center = _centroid(guide_cells)

    shape_groups = {}
    for color, cells in objects:
        if cells == guide_cells:
            continue
        shape_groups.setdefault(_canonical_shape(cells), []).append((color, cells))

    candidates = []
    for group in shape_groups.values():
        if len(group) >= 2:
            candidates.extend((color, cells) for color, cells in group if _nonlinear_or_single(cells))
    if not candidates:
        return [row[:] for row in grid]

    seven_candidates = [(color, cells) for color, cells in candidates if color == 7]
    if seven_candidates:
        smallest = min(len(cells) for color, cells in seven_candidates)
        candidates = [(color, cells) for color, cells in seven_candidates if len(cells) == smallest]

    target_color, target_cells = max(
        candidates,
        key=lambda item: (
            (_centroid(item[1])[0] - guide_center[0]) ** 2
            + (_centroid(item[1])[1] - guide_center[1]) ** 2
        ),
    )
    output = [row[:] for row in grid]
    for r, c in target_cells:
        output[r][c] = guide_color
    return output
